import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient
from fastapi.dependencies.utils import get_typed_return_annotation

def test_get_typed_return_annotation_none_string():
    def route_fn() -> "None":
        return None

    annotation = get_typed_return_annotation(route_fn)
    assert annotation is None

def test_get_typed_return_annotation_none_type():
    def route_fn() -> None:
        return None

    annotation = get_typed_return_annotation(route_fn)
    assert annotation is None

def test_get_typed_return_annotation_empty():
    def route_fn():
        return None

    annotation = get_typed_return_annotation(route_fn)
    assert annotation is None

def test_get_typed_return_annotation_int():
    def route_fn() -> int:
        return 1

    annotation = get_typed_return_annotation(route_fn)
    assert annotation is int

